Custom Themes with CSS

Linking a custom stylesheet
format:
  html:
    theme: flatly
    css: custom.css


Useful CSS overrides for publication style
/* custom.css */

/* Typography */
body {
  font-family: "Georgia", serif;
  font-size: 16px;
  line-height: 1.8;
  max-width: 780px;
  margin: 0 auto;
}

/* Figure captions */
.figure-caption, figcaption {
  font-size: 0.85em;
  color: #555;
  font-style: italic;
  text-align: center;
  margin-top: 0.4em;
}

/* Table caption */
caption {
  font-weight: bold;
  text-align: left;
  margin-bottom: 0.5em;
}

/* Callout notes styled as journal "boxes" */
.callout-note {
  border-left: 4px solid #2c7bb6;
  background: #f0f7ff;
}

/* Reduce heading sizes for manuscript feel */
h1 { font-size: 1.6rem; }
h2 { font-size: 1.3rem; border-bottom: 1px solid #ddd; padding-bottom: 0.2em; }
h3 { font-size: 1.1rem; }

save_plot_multiple_formats &lt;- function(plot, filename_base, 
                                     formats = c("png", "pdf", "svg")) {
  for (fmt in formats) {
    filename &lt;- paste0(filename_base, ".", fmt)
    ggsave(filename, plot, width = 8, height = 6)
  }
}

# Usage
p &lt;- ggplot(mtcars, aes(x = wt, y = mpg)) + geom_point()
save_plot_multiple_formats(p, "mtcars_scatter")



datasets &lt;- list(
  mtcars = mtcars,
  iris = iris,
  airquality = airquality
)

for (name in names(datasets)) {
  data &lt;- datasets[[name]]
  # Create appropriate plot based on data
  if (name == "mtcars") {
    p &lt;- ggplot(data, aes(x = wt, y = mpg)) + geom_point()
  } else if (name == "iris") {
    p &lt;- ggplot(data, aes(x = Sepal.Length, y = Sepal.Width, color = Species)) + 
      geom_point()
  }

  ggsave(paste0(name, "_plot.png"), p, width = 6, height = 4)
}

check_plot_quality &lt;- function(filename) {
  # Check file exists
  if (!file.exists(filename)) {
    stop("File was not created")
  }

  # Check file size (basic quality indicator)
  size &lt;- file.info(filename)$size
  if (size &lt; 1000) {
    warning("File seems too small, may indicate error")
  }

  # For images, could check dimensions
  if (grepl("\\.png$", filename)) {
    img &lt;- png::readPNG(filename)
    message("Image dimensions: ", dim(img)[1], "x", dim(img)[2])
  }
}

# Usage
ggsave("test_plot.png", ggplot(mtcars, aes(x = wt, y = mpg)) + geom_point())
check_plot_quality("test_plot.png")

Functions and Control Flow

Functions are reusable blocks of code created with function()
Control flow uses if, else, for, while and repeat



Show the code
add &lt;- function(a, b) {
  result &lt;- a + b
  return(result)
}

if (add(2, 3) &gt; 4) {
  print("Yes, it is greater than 4")
}



Functions help organize logic and avoid repetition
Control flow enables conditional decisions and loops

